import { View, Text, Pressable, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

function App() {
  const [qty, setQty] = useState(1);
  return (
    <View style={styles.s}>
      <Text style={styles.name}>Гутал</Text>
      <View style={styles.row}>
        <Pressable nativeID="dec" style={styles.btn} onPress={() => setQty((q) => Math.max(1, q - 1))}>
          <Text style={styles.bt}>−</Text>
        </Pressable>
        <Text nativeID="qty" style={styles.qty}>{qty}</Text>
        <Pressable nativeID="inc" style={styles.btn} onPress={() => setQty((q) => q + 1)}>
          <Text style={styles.bt}>+</Text>
        </Pressable>
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, padding: 24, gap: 20, justifyContent: "center", alignItems: "center" },
  name: { fontSize: 20, fontWeight: "600" },
  row: { flexDirection: "row", alignItems: "center", gap: 20 },
  btn: { backgroundColor: "#e5e7eb", width: 44, height: 44, borderRadius: 22, alignItems: "center", justifyContent: "center" },
  bt: { fontSize: 22, fontWeight: "bold" },
  qty: { fontSize: 24, fontWeight: "bold", minWidth: 40, textAlign: "center" },
});

registerRootComponent(App);
